mapper.select:
SELECT a.id, a.title, a.activity_type AS activityType, a.start_time AS startTime, a.end_time AS endTime, f.url AS coverImageUrl FROM activity a LEFT JOIN stored_file f ON a.cover_file_id = f.id WHERE a.status = 'PUBLISHED' AND a.end_time >= NOW()
AND a.street_area_id = #{streetAreaId}
ORDER BY a.start_time ASC LIMIT 50

SELECT r.id, r.name, r.theme, r.estimated_duration AS estimatedDuration FROM experience_route r WHERE r.status = 'ACTIVE'
AND r.street_area_id = #{streetAreaId}
ORDER BY r.id ASC LIMIT 50
